sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '' || newValue === oldValue) {
        return;
    }

    var modifiedReason = newValue.replace(/,/g, " ");
    var totalCharacters = modifiedReason.length;

    if (totalCharacters > 80) {
        g_form.showFieldMsg('reason', 'Length cannot exceed 80 characters', 'error');
        return;
    }

    var finalValue = modifiedReason.replace(/\s+/g, ",").trim();
    if (newValue !== finalValue) {
        g_form.setValue('reason', finalValue);
    }
	else{
		return;
	}
	}
